 const labels={observing:'Observing · 4 / 10 min',healthy:'Recovered · 10 / 10 min',regression:'Regression · rollback review',missing:'Unknown · telemetry gap'};$('watch-state').textContent=labels[state];$('watch-state').className='pill '+(state==='healthy'?'healthy':state==='regression'?'danger':'amber');
 $('error-rate').textContent=state==='missing'?'—':state==='regression'?'6.1%':'0.3%';$('replicas').textContent=state==='missing'?'Unknown':state==='regression'?'2 / 3':'3 / 3';$('freshness').textContent=state==='missing'?'Last sample 4 minutes ago':'Last sample 12 seconds ago';
